"""Compact, deterministic spelling of checked primitive HIA Core.

This frontend supplies syntax only. Types, effects, ownership, calls, CFG edges,
integer modes and attributes stay explicit, and the existing whole-program
verifier remains the sole semantic authority. No expression synthesis, repair,
automatic cast, inferred cleanup, optimizer, or second evaluator lives here.
"""
from __future__ import annotations

from hashlib import sha256
import json
import re

from .hia_json_preflight import preflight_hia_json
from .hia_program import HIAProgramRejected, VerifiedProgram, verify_program
from .hia_program_tools import HIAEditRejected, decode_json
from .hia_schema import SCHEMA_V6, SCHEMA_V7, SCHEMA_V8

ASSEMBLY_SCHEMA = "hepta.hia.agent-assembly.v1"
WIRE_HEADER = "hia-asm.v1"
CORE_SCHEMAS = frozenset({SCHEMA_V6, SCHEMA_V7, SCHEMA_V8})
MAX_SOURCE_BYTES = 1024 * 1024
MAX_LINES = 16384
MAX_LINE_BYTES = 16384
MAX_FUNCTIONS = 256
MAX_BLOCKS = 4096
MAX_OPERATIONS = 16384
MAX_LIST_ITEMS = 256
MAX_ATTRIBUTE_NODES = 2048
MAX_ATTRIBUTE_DEPTH = 16

_NAME = r"[A-Za-z_][A-Za-z_0-9]{0,127}"
_OPCODE = r"[A-Za-z_][A-Za-z_0-9.]{0,127}"
_HEADER = re.compile(rf"{re.escape(WIRE_HEADER)}\s+(\S+)\s+({_NAME})")
_FUNCTION = re.compile(
    rf"fn\s+({_NAME})\(([^()]*)\)\s*->\s*\(([^()]*)\)"
    rf"\s+effects\(([^()]*)\)\s+entry\(({_NAME})\)"
    rf"(?:\s+return_loans\(([^()]*)\))?")
_BLOCK = re.compile(rf"block\s+({_NAME})\(([^()]*)\)")
_INSTRUCTION = re.compile(rf"([^=]+)\s*=\s*({_OPCODE})\(([^()]*)\)(?:\s+(.*))?")
_RETURN = re.compile(r"ret\(([^()]*)\)")
_JUMP = re.compile(rf"jump\s+({_NAME})\(([^()]*)\)")
_BRANCH = re.compile(rf"branch\s+({_NAME})\s+({_NAME})\(([^()]*)\)\s+({_NAME})\(([^()]*)\)")
_TRAP = re.compile(rf"trap\s+({_NAME})")
_SOURCE_CONTROL = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f\ufeff]")


class HIAAssemblyRejected(HIAProgramRejected):
    """A bounded syntax/representation refusal or the original Core refusal."""

    def __init__(self, message, code="E_HIA_ASSEMBLY", *, line=None, phase="syntax"):
        self.line = line
        self.phase = phase
        super().__init__((f"line {line}: " if line is not None else "") + message, code)


def _reject(message, *, line=None, limit=False):
    raise HIAAssemblyRejected(message, "E_HIA_ASSEMBLY_LIMIT" if limit else "E_HIA_ASSEMBLY",
                              line=line)


def _source(value):
    if type(value) not in (str, bytes):
        _reject("source must be UTF-8 text or bytes")
    if len(value) > MAX_SOURCE_BYTES:
        _reject("source exceeds byte budget", limit=True)
    try:
        raw = value.encode("utf-8") if type(value) is str else value
        if len(raw) > MAX_SOURCE_BYTES:
            _reject("source exceeds byte budget", limit=True)
        text = raw.decode("utf-8")
    except UnicodeError as exc:
        raise HIAAssemblyRejected("source is not valid UTF-8") from exc
    # LF and optional CRLF are the only line separators. Do not let Unicode
    # splitlines(), NUL, BOM or terminal controls change visible tokenization.
    # The pattern is the exact rejected set from the character-wise check:
    # ASCII controls except TAB/LF/CR, plus BOM. UTF-8 and source-size checks
    # still precede it, and the separate CRLF/line checks still follow it.
    if _SOURCE_CONTROL.search(text) is not None:
        _reject("unsupported control character or byte-order mark")
    lines = text.split("\n")
    if len(lines) > MAX_LINES:
        _reject("source exceeds line budget", limit=True)
    for number, line in enumerate(lines, 1):
        if len(line.encode("utf-8")) > MAX_LINE_BYTES:
            _reject("line exceeds byte budget", line=number, limit=True)
        if "\r" in line.removesuffix("\r"):
            _reject("carriage return must be part of CRLF", line=number)
    return raw, lines


def _items(value, line):
    if not value.strip():
        return []
    parts = [part.strip() for part in value.split(",")]
    if len(parts) > MAX_LIST_ITEMS:
        _reject("list exceeds item budget", line=line, limit=True)
    if any(not part for part in parts):
        _reject("empty list item", line=line)
    return parts


def _names(value, line):
    parts = _items(value, line)
    if any(re.fullmatch(_NAME, part) is None for part in parts):
        _reject("expected explicit ASCII names", line=line)
    return parts


def _parameters(value, line):
    result = []
    for part in _items(value, line):
        match = re.fullmatch(rf"({_NAME})\s*:\s*({_NAME})", part)
        if match is None:
            _reject("expected name:type for every value", line=line)
        result.append({"name": match[1], "type": match[2]})
    return result


def _attrs(value, line):
    if value is None:
        return {}
    try:
        preflight_hia_json(value, max_nodes=MAX_ATTRIBUTE_NODES,
                          max_depth=MAX_ATTRIBUTE_DEPTH)
        attrs = decode_json(value)
    except (ValueError, OverflowError, HIAEditRejected) as exc:
        raise HIAAssemblyRejected("attributes require bounded strict JSON", line=line) from exc
    if type(attrs) is not dict:
        _reject("attributes must be one JSON object", line=line)
    return attrs


def _parse_assembly_document(source: str | bytes) -> dict:
    """Construct a fresh syntax document without granting Core authority.

    The same source, syntax and attribute bounds apply. The returned mutable
    document is not verified; public callers use assemble_program. Internal
    fixture authors may transform it before their final independent admission.
    No parsed document, VerifiedProgram or admission result is cached.
    """
    _, lines = _source(source)
    document = None
    function = block = None
    blocks = operations = 0
    for number, raw in enumerate(lines, 1):
        line = raw.removesuffix("\r").strip(" \t")
        if not line:
            continue
        if document is None:
            match = _HEADER.fullmatch(line)
            if match is None or match[1] not in CORE_SCHEMAS:
                _reject("expected hia-asm.v1, explicit primitive v6/v7/v8 schema, and module", line=number)
            document = {"schema": match[1], "module": match[2], "functions": []}
            continue
        if function is None:
            exports = re.fullmatch(r"exports\(([^()]*)\)", line)
            if exports is not None:
                if "exports" in document or document["functions"]:
                    _reject("exports may occur once, before all functions", line=number)
                document["exports"] = _names(exports[1], number)
                continue
            match = _FUNCTION.fullmatch(line)
            if match is None:
                _reject("expected explicit function header", line=number)
            if len(document["functions"]) >= MAX_FUNCTIONS:
                _reject("function inventory exceeds budget", line=number, limit=True)
            function = {"name": match[1], "params": _parameters(match[2], number),
                        "returns": _names(match[3], number), "effects": _names(match[4], number),
                        "entry": match[5], "blocks": []}
            if match[6] is not None:
                if document["schema"] != SCHEMA_V8:
                    _reject("return_loans requires explicit Core v8", line=number)
                try:
                    preflight_hia_json(match[6], max_nodes=MAX_LIST_ITEMS + 1, max_depth=2)
                    origins = decode_json(match[6])
                except (ValueError, OverflowError, HIAEditRejected) as exc:
                    raise HIAAssemblyRejected("return_loans requires bounded strict JSON", line=number) from exc
                if (type(origins) is not list or len(origins) > MAX_LIST_ITEMS
                        or any(x is not None and (type(x) is not str or re.fullmatch(_NAME, x) is None)
                               for x in origins)):
                    _reject("return_loans requires a list of formal names or null", line=number)
                function["return_loans"] = origins
            document["functions"].append(function)
            block = None
            continue
        if line == "end":
            if block is None or "term" not in block:
                _reject("function must end after a block terminator", line=number)
            function = block = None
            continue
        match = _BLOCK.fullmatch(line)
        if match is not None:
            if block is not None and "term" not in block:
                _reject("previous block has no terminator", line=number)
            blocks += 1
            if blocks > MAX_BLOCKS:
                _reject("block inventory exceeds budget", line=number, limit=True)
            block = {"id": match[1], "params": _parameters(match[2], number), "ops": []}
            function["blocks"].append(block)
            continue
        if block is None or "term" in block:
            _reject("expected block header or function end", line=number)
        if match := _RETURN.fullmatch(line):
            block["term"] = {"op": "ret", "values": _names(match[1], number)}
        elif match := _JUMP.fullmatch(line):
            block["term"] = {"op": "jump", "target": match[1], "args": _names(match[2], number)}
        elif match := _BRANCH.fullmatch(line):
            block["term"] = {"op": "branch", "cond": match[1],
                             "then": {"target": match[2], "args": _names(match[3], number)},
                             "else": {"target": match[4], "args": _names(match[5], number)}}
        elif match := _TRAP.fullmatch(line):
            block["term"] = {"op": "trap", "code": match[1]}
        elif match := _INSTRUCTION.fullmatch(line):
            operations += 1
            if operations > MAX_OPERATIONS:
                _reject("operation inventory exceeds budget", line=number, limit=True)
            block["ops"].append({"op": match[2], "args": _names(match[3], number),
                                 "out": [] if match[1].strip() == "_" else _parameters(match[1], number),
                                 "attrs": _attrs(match[4], number)})
        else:
            _reject("expected typed instruction or explicit terminator", line=number)
    if document is None:
        _reject("missing assembly header")
    if function is not None:
        _reject("unterminated function; explicit end required", line=len(lines))
    return document


def assemble_program(source: str | bytes) -> VerifiedProgram:
    """Translate explicit assembly to Core and reverify the entire program.

    v6/v7/v8 are the text targets. Historical schemas require their existing
    explicit adapters, and nominal layouts require their existing elaborator.
    """
    document = _parse_assembly_document(source)
    try:
        return verify_program(document)
    except HIAProgramRejected as exc:
        # Core errors are kept as Core errors. An absent location is honest:
        # assigning a guessed syntax line would misidentify cross-block errors.
        raise HIAAssemblyRejected(str(exc).removeprefix(exc.code + ": "), exc.code,
                                  phase="core_verification") from exc


def _render_parameters(parameters):
    return ",".join(p["name"] + ":" + p["type"] for p in parameters)


def _render_assembly_document(data: dict) -> str:
    """Spell a construction document without claiming it is valid Core.

    The input remains owned by the caller and is only read. This helper grants
    no VerifiedProgram or execution authority and performs no admission. The
    public renderer below still fully verifies both the input and round trip.
    """
    lines = [f'{WIRE_HEADER} {data["schema"]} {data["module"]}']
    if "exports" in data:
        lines.append("exports(" + ",".join(data["exports"]) + ")")
    for function in data["functions"]:
        lines.append(f'fn {function["name"]}({_render_parameters(function["params"])}) -> '
                     f'({",".join(function["returns"])}) effects({",".join(function["effects"])}) '
                     f'entry({function["entry"]})')
        if "return_loans" in function:
            lines[-1] += " return_loans(" + json.dumps(function["return_loans"], separators=(",", ":")) + ")"
        for block in function["blocks"]:
            lines.append(f'block {block["id"]}({_render_parameters(block["params"])})')
            for instruction in block["ops"]:
                outputs = _render_parameters(instruction["out"]) or "_"
                text = f'  {outputs} = {instruction["op"]}({",".join(instruction["args"])})'
                if instruction["attrs"]:
                    text += " " + json.dumps(instruction["attrs"], sort_keys=True, separators=(",", ":"),
                                             ensure_ascii=False, allow_nan=False)
                lines.append(text)
            term = block["term"]
            if term["op"] == "ret":
                text = "ret(" + ",".join(term["values"]) + ")"
            elif term["op"] == "jump":
                text = f'jump {term["target"]}({",".join(term["args"])})'
            elif term["op"] == "branch":
                left, right = term["then"], term["else"]
                text = (f'branch {term["cond"]} {left["target"]}({",".join(left["args"])}) '
                        f'{right["target"]}({",".join(right["args"])})')
            else:
                text = "trap " + term["code"]
            lines.append("  " + text)
        lines.append("end")
    return "\n".join(lines) + "\n"


def render_assembly(document) -> str:
    """Canonical compact text whose exact primitive Core round trip is checked."""
    checked = verify_program(document)
    data = checked.as_dict()
    if checked.structured_bytes is not None or data["schema"] not in CORE_SCHEMAS:
        raise HIAAssemblyRejected("render requires explicit primitive v6/v7/v8 Core; use the existing adapter first",
                                  "E_HIA_ASSEMBLY_PROFILE", phase="representation")
    rendered = _render_assembly_document(data)
    if assemble_program(rendered).canonical_bytes != checked.canonical_bytes:
        raise HIAAssemblyRejected("renderer changed canonical Core", "E_HIA_ASSEMBLY_ROUNDTRIP",
                                  phase="representation")
    return rendered


def diagnose_assembly(source: str | bytes) -> dict:
    """Stable Agent diagnostic; accepted syntax/Core grants no native authority."""
    result = {"schema": "hepta.hia.assembly-diagnostic.v1", "accepted": False,
              "deployment_authority": False, "safety_certificate": False,
              "native_artifact_created": False}
    try:
        raw, _ = _source(source)
        result.update(source_sha256=sha256(raw).hexdigest(), source_bytes=len(raw))
        checked = assemble_program(raw)
    except HIAProgramRejected as exc:
        result["diagnostic"] = {"code": exc.code, "message": str(exc),
                                "phase": getattr(exc, "phase", "core_verification"),
                                "line": getattr(exc, "line", None)}
        return result
    result.update(accepted=True, core_sha256=checked.sha256,
                  core_schema=checked.as_dict()["schema"], diagnostic=None)
    return result

hepta/hia_json_decode.py.text:
"""Explicit HIA arena selection for existing bounded JSON consumers.

Default decoding remains the independent Python reference. Native selection
replaces payload parsing, not the host object ABI, Core checks or canonicalizer.
"""
from __future__ import annotations
import json
import os
from .hia_json_preflight import preflight_hia_json


def decode_hia_json(text: str, *, max_nodes: int, max_depth: int,
                    object_pairs_hook=None, parse_int=None, parse_constant=None):
    if (type(text) is not str or type(max_nodes) is not int or max_nodes < 1
            or type(max_depth) is not int or max_depth < 0):
        raise ValueError('invalid HIA JSON decoder input/budgets')
    manifest = os.environ.get('HEPTA_HIA_JSON_DECODE_MANIFEST')
    if manifest and max_nodes <= 1048576 and max_depth <= 128:
        try:
            wire = text.encode('utf-8')
        except UnicodeEncodeError:
            pass
        else:
            if len(wire) <= 8388608:
                from .hia_json_decode_native import installed_decoder
                return installed_decoder(manifest).decode(
                    wire, max_nodes=max_nodes, max_depth=max_depth,
                    object_pairs_hook=object_pairs_hook, parse_int=parse_int)
    preflight_hia_json(text, max_nodes=max_nodes, max_depth=max_depth)
    options = {}
    for name, value in (('object_pairs_hook', object_pairs_hook),
                        ('parse_int', parse_int), ('parse_constant', parse_constant)):
        if value is not None:
            options[name] = value
    return json.loads(text, **options)


def decode_internal_canonical(wire: bytes, *, max_nodes: int, max_depth: int):
    """Detach our own already checked canonical output, without a second scan
    on the default path. A selected HIA decoder also handles this foreign-object
    bridge; no Python JSON parser is then used for the canonical payload.

    This is not an untrusted-input entry or permission to omit structure checks.
    """
    manifest = os.environ.get('HEPTA_HIA_JSON_DECODE_MANIFEST')
    if (manifest and max_nodes <= 1048576 and max_depth <= 128 and len(wire) <= 8388608):
        from .hia_json_decode_native import installed_decoder
        return installed_decoder(manifest).decode(wire, max_nodes=max_nodes, max_depth=max_depth)
    return json.loads(wire)

hepta/hia_json_preflight.py.text:
"""Bounded JSON syntax preflight for the existing HIA decoder.

This small scanner never materializes a JSON *value* tree. It rejects over-budget
node counts, excessive depth, and duplicate object keys BEFORE json.loads
allocates the value graph. The stdlib decoder remains the only producer of
actual JSON values and the unchanged HIA checker remains the semantic authority.
The scanner accepts only the existing HIA integer/string/bool/null subset;
fractional and nonfinite numbers were already rejected by HIA's _structure.
"""
from __future__ import annotations

import json
import os
import re


# Skip only spans which the reference grammar treats identically. Escapes,
# quote boundaries, controls and surrogate code points still reach the same
# ordered checks below; no parsed value or previous admission is reused.
_STRING_BOUNDARY = re.compile(r'["\\\x00-\x1f\ud800-\udfff]')
_WHITESPACE_SPAN = re.compile(r'[ \t\n\r]+')
_DIGIT_SPAN = re.compile(r'[0-9]+')


def preflight_hia_json(text: str, *, max_nodes: int, max_depth: int) -> None:
    """Use an explicitly installed HIA candidate inside its declared profile.

    Without the operator-selected manifest, retain the independent Python path.
    Inputs outside the native profile retain the old API; a broken selected
    artifact fails closed, never silently falls back after a native error.
    No JSON payload can select executable code or change the manifest.
    """
    if (type(text) is not str or type(max_nodes) is not int or max_nodes < 1
            or type(max_depth) is not int or max_depth < 0):
        raise ValueError("invalid HIA JSON preflight input/budgets")
    manifest = os.environ.get('HEPTA_HIA_JSON_PREFLIGHT_MANIFEST')
    if manifest and max_nodes <= 1048576 and max_depth <= 128:
        try:
            wire = text.encode('utf-8')
        except UnicodeEncodeError:
            # Python str may contain isolated surrogates. Those are not UTF-8
            # wire inputs; keep the reference's grammar/budget error ordering.
            pass
        else:
            if len(wire) <= 8388608:
                from .hia_json_preflight_native import installed_preflight
                installed_preflight(manifest).admit(wire, max_nodes=max_nodes, max_depth=max_depth)
                return
    _preflight_hia_json_reference(text, max_nodes=max_nodes, max_depth=max_depth)


def _preflight_hia_json_reference(text: str, *, max_nodes: int, max_depth: int) -> None:
    """Enforce the same root-at-depth-zero value budget as HIA _structure.

    Keys are not structural nodes; array elements and object *values* are.
    Duplicate object keys compare their decoded spellings, including \\u escapes.
    Does not emit any parsed values or trust a claimed schema or proof flag.
    """
    if (type(text) is not str or type(max_nodes) is not int or max_nodes < 1
            or type(max_depth) is not int or max_depth < 0):
        raise ValueError("invalid HIA JSON preflight input/budgets")
    size, index, nodes = len(text), 0, 0
    stack: list[dict] = []
    want_value, done = True, False

    def fail(reason: str) -> None:
        raise ValueError("HIA JSON preflight: " + reason)

    def whitespace() -> None:
        nonlocal index
        if index < size and text[index] in " \t\n\r":
            index = _WHITESPACE_SPAN.match(text, index).end()

    def string_token() -> str:
        nonlocal index
        if index >= size or text[index] != '"':
            fail("expected JSON string")
        first = index
        index += 1
        while index < size:
            boundary = _STRING_BOUNDARY.search(text, index)
            if boundary is None:
                # All remaining characters were ordinary string contents;
                # the original scanner would reach the same missing quote.
                index = size
                break
            index = boundary.start()
            ch = text[index]
            index += 1
            if ch == '"':
                return text[first:index]
            if ord(ch) < 32 or 0xD800 <= ord(ch) <= 0xDFFF:
                fail("unescaped control or isolated Unicode surrogate")
            if ch != "\\":
                continue
            if index >= size:
                fail("unterminated JSON escape")
            esc = text[index]
            index += 1
            if esc in '"\\/bfnrt':
                continue
            if esc != "u" or index + 4 > size:
                fail("invalid JSON escape")
            if any(c not in "0123456789abcdefABCDEF" for c in text[index:index + 4]):
                fail("invalid Unicode escape")
            code_unit = int(text[index:index + 4], 16)
            index += 4
            # HIA's UTF-8 canonical wire format cannot contain isolated
            # UTF-16 surrogate code units. Reject them before json.loads
            # materializes Agent values. A high unit must be immediately
            # followed by the exact escaped low unit in the same token.
            if 0xD800 <= code_unit <= 0xDBFF:
                if (index + 6 > size or text[index:index + 2] != "\\u"
                        or any(c not in "0123456789abcdefABCDEF"
                               for c in text[index + 2:index + 6])
                        or not 0xDC00 <= int(text[index + 2:index + 6], 16) <= 0xDFFF):
                    fail("unpaired high Unicode surrogate")
                index += 6
            elif 0xDC00 <= code_unit <= 0xDFFF:
                fail("unpaired low Unicode surrogate")
        fail("unterminated JSON string")

    def atom() -> None:
        nonlocal index
        if index >= size:
            fail("missing JSON value")
        for keyword in ("true", "false", "null"):
            if text.startswith(keyword, index):
                index += len(keyword)
                return
        if text[index] == '"':
            string_token()
            return
        if text[index] == "-":
            index += 1
        if index >= size or not text[index].isascii() or not text[index].isdigit():
            fail("expected JSON integer or literal")
        if text[index] == "0":
            index += 1
        else:
            index = _DIGIT_SPAN.match(text, index).end()
        # We intentionally decline fractions/exponents: HIA never admits a
        # floating-point JSON node, and stdlib JSON decoding still follows.

    def complete_value() -> None:
        nonlocal done
        if not stack:
            done = True
        elif stack[-1]["state"] != "waiting":
            fail("unexpected value completion")
        else:
            stack[-1]["state"] = "after"

    while True:
        whitespace()
        if done:
            if index != size:
                fail("extra JSON data")
            return
        if want_value:
            if index >= size:
                fail("missing JSON value")
            nodes += 1
            if nodes > max_nodes or len(stack) > max_depth:
                raise OverflowError("HIA JSON exceeds node/depth budget before decoding")
            if text[index] == "[":
                index += 1
                stack.append({"kind": "array", "state": "first"})
            elif text[index] == "{":
                index += 1
                stack.append({"kind": "object", "state": "first", "keys": set()})
            else:
                atom()
                complete_value()
            want_value = False
            continue
        if not stack:
            fail("incomplete JSON value")
        frame = stack[-1]
        state, kind = frame["state"], frame["kind"]
        ch = text[index] if index < size else None
        if kind == "array":
            if state in {"first", "element"}:
                if state == "first" and ch == "]":
                    index += 1
                    stack.pop()
                    complete_value()
                else:
                    frame["state"] = "waiting"
                    want_value = True
            elif state == "after":
                if ch == ",":
                    index += 1
                    frame["state"] = "element"
                elif ch == "]":
                    index += 1
                    stack.pop()
                    complete_value()
                else:
                    fail("expected array separator/end")
            else:
                fail("invalid array preflight state")
        else:
            if state in {"first", "key"}:
                if state == "first" and ch == "}":
                    index += 1
                    stack.pop()
                    complete_value()
                elif ch == '"':
                    token = string_token()
                    key = json.loads(token)
                    if key in frame["keys"]:
                        fail("duplicate decoded object key")
                    frame["keys"].add(key)
                    frame["state"] = "colon"
                else:
                    fail("expected object field name")
            elif state == "colon":
                if ch != ":":
                    fail("expected object colon")
                index += 1
                frame["state"] = "value"
            elif state == "value":
                frame["state"] = "waiting"
                want_value = True
            elif state == "after":
                if ch == ",":
                    index += 1
                    frame["state"] = "key"
                elif ch == "}":
                    index += 1
                    stack.pop()
                    complete_value()
                else:
                    fail("expected object separator/end")
            else:
                fail("invalid object preflight state")

