def coordinator_note_lifetime(call,replacement):
    trace=[];references={}
    def created(cls,message):
        result=cls(message);references[message]=weakref.ref(result);return result
    class Leaf:
        @property
        def __class__(self):raise created(NoteChildError,"child")
        def __del__(self):trace.append("leaf_del")
    class Key(str):
        def __repr__(self):
            trace.append("key_repr")
            if replacement:raise created(NoteReplacement,"replacement")
            return "<key>"
        def __del__(self):trace.append("key_del")
    class Mapping(dict):
        def items(self):
            trace.append("items")
            return [(Key("key"),Leaf())]
    root=baseline["late"](Mapping(physical=0),trace,True)
    root_ref=weakref.ref(root)
    held=None
    try:call(root)
    except BaseException as error:
        held=error
        result={"exception":note_state(error)}
    else:raise AssertionError("lifetime fixture did not raise")
    root=None
    result["while_held"]={"root_alive":root_ref() is not None,
        "exceptions_alive":{name:ref() is not None for name,ref in references.items()},
        "trace":list(trace)}
    held=None
    result["after_release"]={"root_alive":root_ref() is not None,
        "exceptions_alive":{name:ref() is not None for name,ref in references.items()},
        "trace":list(trace)}
    assert result["while_held"]["root_alive"] and not result["after_release"]["root_alive"],result
    assert not any(result["after_release"]["exceptions_alive"].values()),result
    return result

