    note_calls=[]
    note_type=type(owner.notes);note_entry=note_type.note
    def counted_note(self,*args):
        note_calls.append(args[1])
        return note_entry(self,*args)
    injected=KeyboardInterrupt("lost note acknowledgement")
    injected_seen=False
